"use client";

import { useCallback, useEffect, useState, type ComponentType } from "react";
import type { DotLottie, DotLottieReactProps } from "@lottiefiles/dotlottie-react";
import { useReducedMotion } from "@/lib/motion";

/**
 * Both files are generated by `npm run motion:lottie`
 * (scripts/motion/build-lottie.ts). The renderer is self-hosted because
 * dotLottie's default is to fetch it from jsDelivr, and a loader that waits on
 * a third-party CDN shows nothing exactly when the network is being slow.
 */
const SRC = "/lottie/tape-loader.json";
const WASM = "/lottie/dotlottie-player.wasm";

type PlayerComponent = ComponentType<DotLottieReactProps>;

let loading: Promise<PlayerComponent> | null = null;

/**
 * The player and its renderer load on first use, never with the page: the
 * loader only appears while the Selector is waiting on the model, and the
 * home route shouldn't carry the player (~33 kB gzipped, plus a ~485 kB
 * gzipped WASM renderer) for a moment most visits never reach.
 *
 * Not next/dynamic: React.lazy rethrows a failed chunk while rendering, which
 * took the whole route down to app/error.tsx — for a decoration, offline,
 * while the Selector itself carries on in keyword mode. Here a failure is
 * the caller's to swallow, and it isn't cached: the next loader asks again,
 * so the cassette comes back once the network does.
 */
function loadPlayer(): Promise<PlayerComponent> {
  loading ??= import("@lottiefiles/dotlottie-react").then(
    (m) => {
      m.setWasmUrl(WASM);
      return m.DotLottieReact;
    },
    (err: unknown) => {
      loading = null;
      throw err;
    },
  );
  return loading;
}

/**
 * The fallback's reels, in the artboard's own numbers (240x120: supply reel
 * r27 at x90, take-up r18 at x150, both on y60, hubs r10.5 in a r12.5 gap), so
 * when the cassette fades in round them nothing jumps.
 *
 * The hubs turn as the Lottie's do — anticlockwise, the supply reel 240° and
 * the take-up 360° per two-second loop (ω = v / r) — so the row is already
 * moving while the player is still downloading, which on a cold mobile cache
 * can take as long as the answer it is waiting on.
 */
const HUB = 10.5;
const GAP = 12.5;
const REELS = [
  { x: 90, r: 27, turn: "3s" },
  { x: 150, r: 18, turn: "2s" },
].map(({ x, r, turn }) => ({
  pack: {
    left: `${((x - r) / 240) * 100}%`,
    top: `${((60 - r) / 120) * 100}%`,
    width: `${((r * 2) / 240) * 100}%`,
    height: `${((r * 2) / 120) * 100}%`,
    background: `radial-gradient(closest-side, #0b0d10 ${(GAP / r) * 100}%, #3a2a20 0)`,
  },
  hub: {
    width: `${(HUB / r) * 100}%`,
    height: `${(HUB / r) * 100}%`,
    // Top to bottom: the spindle, the rim, and six cream spokes (wedges here;
    // at 7px across nobody can tell) over the dark spindle hole, one upright
    // as in the Lottie's first frame.
    background: [
      `radial-gradient(closest-side, #0b0d10 ${(2.6 / HUB) * 100}%, transparent 0)`,
      `radial-gradient(closest-side, transparent ${(7.5 / HUB) * 100}%, #efe4cc 0)`,
      "repeating-conic-gradient(from -15deg, #efe4cc 0 30deg, #0b0d10 0 60deg)",
    ].join(", "),
    // animate-spin is clockwise; a reel in play turns the other way.
    animationDuration: turn,
    animationDirection: "reverse",
  },
}));

/**
 * A cassette turning in its window: Pulsar's "working on it" mark.
 *
 * Decorative — it is aria-hidden and the caller says in words what is
 * happening. Give it a 2:1 box via `className`.
 *
 * Until the player has loaded (or for good, if it can't) it shows the two
 * reels drawn in CSS, already turning. Under reduced motion neither moves:
 * the cassette appears on its first frame, which is a complete picture of it.
 */
export function TapeLoader({ className = "h-10 w-20" }: { className?: string }) {
  const reduce = useReducedMotion();
  const [Player, setPlayer] = useState<PlayerComponent | null>(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    let live = true;
    loadPlayer().then(
      (P) => {
        if (live) setPlayer(() => P);
      },
      // Offline, or a deploy replaced the chunk: the CSS reels carry on.
      () => {},
    );
    return () => {
      live = false;
    };
  }, []);

  // dotLottie keeps no React state of its own, so listen for the moment it has
  // drawn the animation and only then swap the fallback out.
  const attach = useCallback((player: DotLottie | null) => {
    if (!player) return;
    if (player.isLoaded) {
      setReady(true);
      return;
    }
    const onLoad = () => {
      player.removeEventListener("load", onLoad);
      setReady(true);
    };
    player.addEventListener("load", onLoad);
  }, []);

  return (
    <div
      aria-hidden
      data-state={ready ? (reduce ? "still" : "playing") : "loading"}
      className={`relative flex-shrink-0 ${className}`}
    >
      <div
        className={`absolute inset-0 transition-opacity duration-200 motion-reduce:transition-none ${
          ready ? "opacity-0" : "opacity-100"
        }`}
      >
        {/* Centred by flex, not translate: animate-spin's transform would
            override a translate class. */}
        {REELS.map(({ pack, hub }, i) => (
          <span key={i} className="absolute flex items-center justify-center rounded-full" style={pack}>
            <span
              data-reel
              className="animate-spin rounded-full motion-reduce:animate-none"
              style={hub}
            />
          </span>
        ))}
      </div>
      {Player && (
        <Player
          src={SRC}
          // Read once, at creation: dotlottie-react doesn't react to a later
          // change. motion's hook already has the real answer by the time the
          // player chunk arrives, and this never renders on the server.
          autoplay={!reduce}
          loop
          renderConfig={{
            autoResize: true,
            // dotLottie's default renders at 75% of the extra density, which
            // softens an 80px-wide drawing; at this size full density is cheap.
            devicePixelRatio: window.devicePixelRatio,
          }}
          dotLottieRefCallback={attach}
          className={`absolute inset-0 transition-opacity duration-200 motion-reduce:transition-none ${
            ready ? "opacity-100" : "opacity-0"
          }`}
        />
      )}
    </div>
  );
}
